use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let lmdfb_data = fs :: read_to_string ("lmdfb_lattice_mapping.json") ? ; let lmdfb : serde_json :: Value = serde_json :: from_str (& lmdfb_data) ? ; let mut usage_reports : HashMap < i32 , NodeUsageReport > = HashMap :: new () ; if let Some (nodes) = lmdfb ["nodes"] . as_object () { for (symbol , node) in nodes { analyze_node_usage (symbol , node , & mut usage_reports) ; } } let mut sorted_reports : Vec < _ > = usage_reports . into_values () . collect () ; sorted_reports . sort_by (| a , b | b . total_usage_count . cmp (& a . total_usage_count)) ; println ! ("🔗 Integer Node Usage & Relations Report") ; println ! ("========================================\n") ; for (i , report) in sorted_reports . iter () . take (20) . enumerate () { println ! ("{}. Integer: {} (Used {} times)" , i + 1 , report . integer_value , report . total_usage_count) ; let mut user_types : Vec < _ > = report . user_types . iter () . collect () ; user_types . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("   👥 User Types: {}" , user_types . iter () . take (3) . map (| (t , c) | format ! ("{}({})" , t , c)) . collect ::< Vec < _ >> () . join (", ")) ; let mut relations : Vec < _ > = report . relations . iter () . collect () ; relations . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("   🔗 Relations: {}" , relations . iter () . take (3) . map (| (r , c) | format ! ("{}({})" , r , c)) . collect ::< Vec < _ >> () . join (", ")) ; let mut contexts : Vec < _ > = report . ast_contexts . iter () . collect () ; contexts . sort_by (| a , b | b . 1 . cmp (a . 1)) ; println ! ("   🌳 AST Contexts: {}" , contexts . iter () . take (3) . map (| (c , n) | format ! ("{}({})" , c , n)) . collect ::< Vec < _ >> () . join (", ")) ; println ! ("   📦 Crates: {} different crates" , report . crate_distribution . len ()) ; println ! () ; } let report_json = serde_json :: to_string_pretty (& sorted_reports) ? ; fs :: write ("integer_usage_relations_report.json" , report_json) ? ; let total_integers = sorted_reports . len () ; let total_usages : usize = sorted_reports . iter () . map (| r | r . total_usage_count) . sum () ; let avg_usage = if total_integers > 0 { total_usages / total_integers } else { 0 } ; println ! ("📊 Summary Statistics:") ; println ! ("   Total unique integers: {}" , total_integers) ; println ! ("   Total usage instances: {}" , total_usages) ; println ! ("   Average usage per integer: {}" , avg_usage) ; println ! ("   Report saved to: integer_usage_relations_report.json") ; Ok (()) }
}